def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Extract yesterday bids only (immediate reaction)
    prev_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    # Estimate competitive pressure from yesterday
    if prev_bids:
        sorted_bids = sorted(prev_bids)
        n = len(sorted_bids)
        median_bid = sorted_bids[int(n // 2)] if n > 0 else 0.0
        max_prev_bid = sorted_bids[-1]
    else:
        median_bid = 0.0
        max_prev_bid = 0.0

    # Supply pressure: with low supply (near 15), we should be more competitive.
    # Normalize supply to [0,1]
    if MAX_SUPPLY <= MIN_SUPPLY:
        supply_ratio = 1.0
    else:
        supply_ratio = (float(supply) - float(MIN_SUPPLY)) / (float(MAX_SUPPLY) - float(MIN_SUPPLY))
        if supply_ratio < 0.0:
            supply_ratio = 0.0
        if supply_ratio > 1.0:
            supply_ratio = 1.0

    # Base target bid: slightly above median yesterday, more aggressive when supply is low.
    # Also cap by a fraction of our budget.
    budget_cap = float(my_status['budget'])

    # If our hp is critical, prioritize survival.
    hp = float(my_status.get('hp', 0))
    no_water_days = float(my_status.get('no_water_days', 0))

    # Aggression factor increases when supply is low and when hp/no_water_days are bad.
    aggression = 1.0
    aggression += (1.0 - supply_ratio) * 0.6
    if hp <= 2.0:
        aggression += 0.8
    elif hp <= 4.0:
        aggression += 0.4
    if no_water_days >= 1.0:
        aggression += 0.2

    # If others were extremely aggressive yesterday, we must match closer to max.
    if max_prev_bid >= DAILY_SALARY * 0.55:
        target = median_bid * (1.0 + 0.08 * aggression) + 2.0
        # Ensure we don't lag too far behind the top bidder.
        target = max(target, max_prev_bid * 0.92)
    else:
        target = median_bid * (1.0 + 0.10 * aggression) + 1.0

    # Ensure we don't overspend early: scale down when hp is healthy.
    if hp >= 7.0:
        target *= 0.85
    elif hp <= 3.0:
        target *= 1.05

    # Final bid bounded by budget and reasonable fraction of daily salary.
    # Use slightly higher fraction than typical to exploit their median behavior.
    fraction = 0.65
    if hp <= 4.0:
        fraction = 0.85
    if supply_ratio < 0.4:
        fraction += 0.1

    max_allowed = min(budget_cap, DAILY_SALARY * fraction)
    bid = float(target)
    if bid < 0.0:
        bid = 0.0
    if bid > max_allowed:
        bid = max_allowed

    # If our budget is tiny, just spend what we can.
    if budget_cap <= 1.0:
        return float(max(0.0, budget_cap))

    # Avoid zero bids when supply is scarce.
    if bid < 1.0 and supply_ratio < 0.7:
        bid = min(max_allowed, 1.0 + (DAILY_SALARY * 0.05))

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    supply_units = int(day_context['supply'] // WATER_REQ)

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    if my_status['hp'] <= 2:
        if day_context['day'] >= EPISODE_DAYS - 2:
             return min(my_status['budget'], DAILY_SALARY * 1.1)
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    base_bid = DAILY_SALARY * 0.55

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.8:
            if my_status['hp'] > 3:
                base_bid = max(base_bid, highest_prev_bid + 2)
            else:
                base_bid = max(base_bid, highest_prev_bid + 5)
        elif avg_prev_bid >= DAILY_SALARY * 0.5:
            base_bid = max(base_bid, avg_prev_bid + 1)
        else:
            base_bid = max(base_bid, DAILY_SALARY * 0.4)

    total_players_needing_water = num_alive_opponents + 1
    if supply_units < total_players_needing_water:
        base_bid *= (1 + (total_players_needing_water - supply_units) * 0.1)
        base_bid = min(base_bid, DAILY_SALARY * 1.05)
    elif supply_units > total_players_needing_water:
        base_bid *= (1 - (supply_units - total_players_needing_water) * 0.05)
        base_bid = max(base_bid, DAILY_SALARY * 0.3)

    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 3 and my_status['hp'] <= 3:
        base_bid = max(base_bid, DAILY_SALARY * 1.0)
    elif my_status['budget'] < base_bid and my_status['hp'] > 2:
        base_bid = min(my_status['budget'], base_bid * 0.8)

    final_bid = max(1.0, base_bid)
    return min(my_status['budget'], final_bid)
